export const reservedFieldCases = ['AND','OR','NOT','XOR'].flatMap(field=>[
  {source:`${field}:red`,query:text('red',[field])},
  {source:`${field} : (red OR blue)`,query:or(text('red',[field]),text('blue',[field]))},
]);
